window.HEB_STORIES=[{"id":"h1","lvl":1,"title":"החתול של דנה","text":"לדנה יש חתול קטן. שם החתול מיצי. מיצי לבן ורך. כל בוקר מיצי שותה חלב מן הקערה. אחר כך הוא משחק בכדור אדום. דנה אוהבת ללטף את מיצי ולשחק איתו בגינה. בערב מיצי עייף והוא ישן על הכר של דנה. דנה שמחה שיש לה חתול נחמד כל כך. בבוקר מיצי מעיר את דנה בקול רך. מיצי אוהב לשבת ליד החלון ולהסתכל על הציפורים בעץ. לפעמים הוא רץ מהר בכל הבית.","qpool":[{"q":"מה שם החתול של דנה?","o":["רקסי","מיצי","פלוף","שחור"],"c":1},{"q":"באיזה צבע החתול?","o":["שחור","חום","לבן","כתום"],"c":2},{"q":"מה מיצי שותה כל בוקר?","o":["חלב","מים","מיץ","תה"],"c":0},{"q":"במה משחק מיצי?","o":["בבובה","במקל","בחבל","בכדור"],"c":3},{"q":"איפה ישן מיצי בערב?","o":["על הרצפה","על הכר של דנה","בגינה","על הכיסא"],"c":1},{"q":"מה מיצי אוהב לראות מהחלון?","o":["כלבים","מכוניות","ציפורים","ילדים"],"c":2},{"q":"מתי מיצי מעיר את דנה?","o":["בבוקר","בערב","בלילה","בצהריים"],"c":0},{"q":"איך מרגישה דנה שיש לה חתול?","o":["עצובה","שמחה","כועסת","פוחדת"],"c":1}]},{"id":"h2","lvl":2,"title":"הטיול ליער","text":"ביום ראשון יצאה הכיתה של נועה לטיול ביער. המורה חילקה לכל ילד תיק קטן עם מים וכריך. הילדים הלכו בשביל צר בין העצים הגבוהים. הם ראו סנאי חום שקפץ מענף לענף, ופרפרים צבעוניים שעפו מעל הפרחים. נועה שמעה ציפורים שרות בין העלים והריחה ריח נעים של אורנים.\n\nבצהריים ישבו כולם על מזרן דשא ואכלו את הכריכים. אחרי האוכל המורה סיפרה על החיות שגרות ביער. היא הסבירה שאסור להשאיר זבל ביער, וכל הילדים אספו את השקיות שלהם. בדרך חזרה מצאה נועה אבן יפה בצורת לב והכניסה אותה לתיק. כשהגיעו לבית הספר, כל הילדים היו עייפים אבל מאוד שמחים. נועה החליטה לספר לאמא שלה על כל מה שקרה ביום המיוחד הזה.","qpool":[{"q":"לאן יצאה הכיתה של נועה?","o":["לים","ליער","למוזיאון","לגן חיות"],"c":1},{"q":"מה חילקה המורה לכל ילד?","o":["תיק עם מים וכריך","ספר","כדור","מפה"],"c":0},{"q":"איזו חיה ראו הילדים קופצת מענף לענף?","o":["ארנב","סנאי","חתול","כלב"],"c":1},{"q":"איפה ישבו הילדים לאכול בצהריים?","o":["על מזרן דשא","על ספסל","על סלע","בכיתה"],"c":0},{"q":"מה מצאה נועה בדרך חזרה?","o":["פרח","אבן בצורת לב","נוצה","מקל"],"c":1},{"q":"מה הסבירה המורה שאסור לעשות ביער?","o":["לרוץ","לצעוק","להשאיר זבל","לטפס"],"c":2},{"q":"איך הרגישו הילדים כשחזרו לבית הספר?","o":["עייפים אבל שמחים","עצובים","רעבים","כועסים"],"c":0},{"q":"למי רצתה נועה לספר על הטיול?","o":["למורה","לאמא שלה","לחברה","לסבתא"],"c":1}]},{"id":"h3","lvl":2,"title":"הגינה של סבא","text":"לסבא של איתי יש גינה גדולה מאחורי הבית. בגינה גדלים עגבניות, מלפפונים ותות שדה מתוק. כל יום שישי איתי בא לעזור לסבא בגינה. הם משקים את הצמחים במים, מוציאים עשבים ומפזרים אדמה שחורה. לפעמים סבא מספר לאיתי סיפורים על הגינה מהזמן שהוא היה ילד קטן.\n\nסבא לימד את איתי שכל צמח צריך שמש ומים כדי לגדול. איתי אוהב במיוחד לקטוף את התותים האדומים ולטעום אותם ישר מהשיח. פעם אחת מצאו בגינה קן קטן של ציפור עם שלוש ביצים כחולות. סבא אמר לאיתי לא לגעת בקן, כדי שהאמא לא תברח. אחרי כמה שבועות בקעו האפרוחים והתחילו לצייץ. איתי היה גאה מאוד שהוא שמר על הקן, וסבא חייך אליו באהבה.","qpool":[{"q":"איפה נמצאת הגינה של סבא?","o":["מאחורי הבית","ליד בית הספר","בפארק","על הגג"],"c":0},{"q":"מה גדל בגינה?","o":["פרחים בלבד","עגבניות, מלפפונים ותות","עצי תפוח","דקלים"],"c":1},{"q":"מתי איתי בא לעזור לסבא?","o":["כל יום שישי","כל יום ראשון","רק בשבת","רק בקיץ"],"c":0},{"q":"מה צריך כל צמח כדי לגדול, לפי סבא?","o":["חושך","שמש ומים","רק אדמה","קור"],"c":1},{"q":"מה איתי אוהב במיוחד לקטוף?","o":["מלפפונים","עגבניות","תותים אדומים","עשבים"],"c":2},{"q":"מה מצאו בגינה?","o":["קן עם ביצים","נחש","חתול","אבן גדולה"],"c":0},{"q":"למה אמר סבא לא לגעת בקן?","o":["כי הוא מלוכלך","כדי שהאמא לא תברח","כי הוא מסוכן","כי הוא רחוק"],"c":1},{"q":"איך הרגיש איתי אחרי שהאפרוחים בקעו?","o":["מפוחד","עצוב","גאה","משועמם"],"c":2}]},{"id":"h4","lvl":3,"title":"המצאה קטנה גדולה","text":"מאיה הייתה ילדה סקרנית שאהבה לפרק ולהרכיב דברים. בכל פעם שמשהו בבית התקלקל, היא רצה לראות מה יש בפנים. היא שמרה בקופסה מיוחדת ברגים, גומיות וחוטים, שאולי יעזרו לה ביום מן הימים. יום אחד שמה לב שסבתא שלה מתקשה לפתוח צנצנות, כי הידיים שלה כואבות. מאיה החליטה שהיא רוצה לעזור לה.\n\nהיא לקחה גומייה עבה וחתיכת בד, וחשבה איך אפשר לתפוס את המכסה חזק יותר. אחרי כמה ניסיונות שנכשלו, היא גילתה שאם עוטפים את המכסה בגומייה, הידיים לא מחליקות והצנצנת נפתחת בקלות. מאיה ניסתה את הפתרון על כמה צנצנות שונות בבית, וכל פעם המכסה נפתח בקלות. סבתא הייתה מאושרת ואמרה שמאיה חכמה כמו ממציאה אמיתית.\n\nבבית הספר סיפרה מאיה למורה על הרעיון שלה. המורה ביקשה ממנה להראות את ההמצאה לכל הכיתה. הילדים התלהבו וכל אחד רצה לנסות בעצמו. מאותו יום הבינה מאיה שגם רעיון פשוט מאוד יכול לעזור לאנשים. היא החליטה שכשתגדל היא תלמד הנדסה ותמציא דברים שיעשו את החיים קלים יותר לכולם.","qpool":[{"q":"מה מאיה אהבה לעשות?","o":["לצייר","לפרק ולהרכיב דברים","לשיר","לרוץ"],"c":1},{"q":"במה התקשתה סבתא?","o":["לפתוח צנצנות","ללכת","לקרוא","לבשל"],"c":0},{"q":"מה החליטה מאיה כשראתה את סבתא מתקשה?","o":["לקנות צנצנות חדשות","לקרוא לרופא","לעזור לה","להתעלם"],"c":2},{"q":"באילו חומרים השתמשה מאיה?","o":["גומייה וחתיכת בד","עץ ומסמרים","נייר ודבק","ברזל"],"c":0},{"q":"מה גילתה מאיה שעוזר לפתוח את המכסה?","o":["מים חמים","לעטוף את המכסה בגומייה","להכות במכסה","לחכות הרבה זמן"],"c":1},{"q":"איך הגיבה סבתא להמצאה?","o":["כעסה","צחקה","הייתה מאושרת","התעצבנה"],"c":2},{"q":"מה ביקשה המורה ממאיה?","o":["לשבת בשקט","לכתוב חיבור","לשכוח מזה","להראות את ההמצאה לכיתה"],"c":3},{"q":"מה החליטה מאיה לעשות כשתגדל?","o":["ללמוד הנדסה ולהמציא דברים","להיות מורה","לגור עם סבתא","לפתוח חנות"],"c":0}]},{"id":"h5","lvl":4,"title":"שומרת המגדלור","text":"על צוק גבוה מעל הים עמד מגדלור ישן, ובו התגוררה ילדה בשם תמר עם סבּה, שומר המגדלור. תפקידו של הסב היה להדליק כל לילה את הפנס הגדול, כדי שהספנים בים יראו את האור ולא יתנפצו על הסלעים. תמר אהבה לטפס במדרגות הלולייניות ולהביט אל האופק הרחוק, והיא הכירה כל פינה ופינה בבניין הגבוה. מאור המגדלור למדה תמר כמה חשוב שיהיה מישהו שנשאר ער ושומר על אחרים גם בשעות הקשות ביותר.\n\nבלילה סוער אחד נשבה רוח חזקה והגשם ניתך בזעם. הגלים הכו בסלעים ברעש אדיר, ותמר הרגישה את ליבה פועם בחוזקה. פתאום כבה הפנס, כי החשמל נפסק. הסב היה חולה במיטתו ולא יכול לקום. תמר ידעה שאונייה קטנה מפליגה באותו לילה, והבינה שאם לא יהיה אור, הספנים עלולים ללכת לאיבוד.\n\nבלי להסס היא הדליקה עשרות נרות והציבה אותם ליד החלון הגדול. היא אחזה מראה ישנה וכיוונה בעזרתה את אור הנרות אל הים. ידיה רעדו מהמאמץ ועיניה נעצמו מעייפות, אך היא לא הרשתה לעצמה לעצום עין ולו לרגע אחד. שעות ארוכות עמדה תמר ולא ויתרה, עד שראתה את האונייה עוגנת בשלום בנמל. למחרת בבוקר סיפרו הספנים בכל העיר על הילדה האמיצה שהצילה אותם. תמר רק חייכה בצניעות ואמרה שכל אחד היה עושה את אותו הדבר.","qpool":[{"q":"מי גר במגדלור יחד עם תמר?","o":["אמא שלה","דוד","סבּה","חבר"],"c":2},{"q":"מה היה תפקידו של הסב?","o":["להדליק את הפנס כל לילה","לדוג דגים","לנקות את הים","לבנות ספינות"],"c":0},{"q":"למה חשוב שהספנים יראו את האור?","o":["כדי שידעו מה השעה","כדי שלא יתנפצו על הסלעים","כדי לשיר","כדי לישון"],"c":1},{"q":"מה קרה בלילה הסוער?","o":["הפנס כבה","המגדלור נפל","תמר ברחה","הים קפא"],"c":0},{"q":"למה הסב לא יכול היה לקום?","o":["היה עסוק","טייל","ישן","היה חולה"],"c":3},{"q":"איך יצרה תמר אור?","o":["הביאה פנס חדש","הדליקה נרות וכיוונה אותם במראה","צעקה בקול","הדליקה מדורה בחוץ"],"c":1},{"q":"מה ראתה תמר בסוף הלילה?","o":["את האונייה עוגנת בשלום","את השמש עולה","את הסב מבריא","את הרוח נרגעת"],"c":0},{"q":"איך הגיבה תמר לשבחים?","o":["התגאתה מאוד","כעסה","חייכה בצניעות","ברחה"],"c":2}]},{"id":"h6","lvl":5,"title":"העץ העתיק של הכפר","text":"בקצה כפר קטן, שנשען על מדרונות ירוקים, ניצב עץ זית עתיק שגילו מאות שנים. תושבי הכפר סיפרו שהעץ ניטע עוד בימי סבי-סבותיהם, וכי ענפיו המפותלים ראו דורות רבים באים והולכים. ילד בשם יונתן נהג לשבת בצל העץ אחרי הלימודים, ולהאזין לרשרוש העלים ברוח. הוא היה מספר לחבריו שהעץ הוא כמו סבא זקן וחכם, ששומר על סודות הכפר.\n\nיום אחד הגיעו לכפר אנשים שביקשו לכרות את העץ כדי לסלול כביש רחב. יונתן נחרד מעצם המחשבה, ובליבו החליט שלא ייתן לזה לקרות, יהיה אשר יהיה. הוא ידע שהעץ אינו רק גזע וענפים, אלא חלק מזיכרונו של הכפר כולו. במקום להתייאש, אסף יונתן את ילדי הכפר וביחד הכינו שלטים ואיורים שסיפרו על ההיסטוריה של העץ.\n\nהם הזמינו את ראש המועצה לשמוע את סיפורו של העץ מפי הזקנים. האנשים ישבו סביב שולחן ארוך והקשיבו בדממה לכל מילה שיצאה מפי הזקן. אחד הזקנים תיאר כיצד בזמן בצורת קשה סיפק העץ שמן זית שהאכיל משפחות רבות. דבריו נגעו ללב כל הנוכחים. לאחר דיון ארוך הוחלט להזיז את תוואי הכביש כמה מטרים הצידה, וכך ניצל העץ העתיק.\n\nמאותו יום הפך העץ לסמל של הכפר. בכל אביב נהגו התושבים להתאסף סביבו, לחגוג ולהודות על שהצליחו לשמור על אוצר חי כל כך. יונתן, שגדל והיה למורה, לימד את תלמידיו שלפעמים דווקא הקטנים והצעירים הם שמצליחים לשנות את דעתם של הגדולים, אם רק אוזרים אומץ ופועלים יחד.","qpool":[{"q":"מה ניצב בקצה הכפר?","o":["מזרקה","מגדל","עץ זית עתיק","נהר"],"c":2},{"q":"מה נהג יונתן לעשות אחרי הלימודים?","o":["לשבת בצל העץ","לשחק כדורגל","לעזור בשדה","לישון"],"c":0},{"q":"למה רצו האנשים לכרות את העץ?","o":["כי היה חולה","כדי לסלול כביש","כדי להסיק","כי הפריע להם"],"c":1},{"q":"מה עשה יונתן במקום להתייאש?","o":["ברח מהכפר","בכה בשקט","הסתתר בבית","אסף את הילדים והכינו שלטים"],"c":3},{"q":"את מי הזמינו לשמוע על סיפורו של העץ?","o":["את המורה","את המשטרה","את ראש המועצה","את ההורים"],"c":2},{"q":"מה סיפר הזקן על העץ בזמן בצורת?","o":["שהעץ נפל","שסיפק שמן זית שהאכיל משפחות","שהעץ יבש","שהעץ נשרף"],"c":1},{"q":"מה הוחלט בסוף הדיון?","o":["לכרות את העץ","לעזוב את הכפר","להזיז את הכביש הצידה","לבנות גדר"],"c":2},{"q":"מה לימד יונתן את תלמידיו?","o":["שצריך תמיד להקשיב למבוגרים","שגם הצעירים יכולים לשנות את דעת הגדולים","שעצים אינם חשובים","שכדאי לוותר בקלות"],"c":1}]},{"id":"h7","lvl":1,"title":"עוגיות עם סבתא","text":"יום שישי בבוקר. רוני הולך לבית של סבתא. סבתא אוהבת לאפות עוגיות.\n\nסבתא נותנת לרוני סינר קטן. הם שמים קמח, סוכר וביצה בקערה. רוני מערבב הכל עם כף גדולה. הבצק רך ומתוק.\n\nרוני עושה עוגיות בצורת לב וכוכב. סבתא שמה את העוגיות בתנור. ריח טוב ממלא את הבית.\n\nאחרי חצי שעה העוגיות מוכנות. הן חמות וזהובות. רוני מחכה שהן יתקררו. אחר כך הוא טועם עוגיה אחת. היא טעימה מאוד!\n\nרוני שם עוגיות בקופסה. הוא רוצה לתת אותן לאמא ולאבא. סבתא מחייכת ואומרת: כל הכבוד, רוני, אתה אופה נהדר.","qpool":[{"q":"מתי רוני הולך לבית של סבתא?","o":["יום שישי בבוקר","יום שבת בערב","יום ראשון בצהריים","יום שני בלילה"],"c":0},{"q":"מה סבתא אוהבת לעשות?","o":["לרוץ בפארק","לקרוא ספר","לאפות עוגיות","לשתות קפה"],"c":2},{"q":"מה סבתא נותנת לרוני?","o":["כובע","סינר קטן","נעליים","מטריה"],"c":1},{"q":"מה שמים בקערה?","o":["מים ומלח","קמח סוכר וביצה","ירקות","חול"],"c":1},{"q":"באילו צורות רוני עושה עוגיות?","o":["עיגול וריבוע","לב וכוכב","פרח ועץ","בית ורכב"],"c":1},{"q":"כמה זמן העוגיות בתנור?","o":["חמש דקות","שעתיים","חצי שעה","יום שלם"],"c":2},{"q":"איך העוגיות בסוף?","o":["קרות ומרות","חמות וזהובות","שרופות","קפואות"],"c":1},{"q":"למי רוני רוצה לתת את העוגיות?","o":["לחתול","למורה","לאמא ולאבא","לשכן"],"c":2}]},{"id":"h8","lvl":2,"title":"האופניים של תמר","text":"תמר בת שבע. יש לה אופניים חדשים בצבע אדום. היא קיבלה אותם ביום ההולדת.\n\nבבוקר תמר יוצאת לחצר עם אבא. היא רוצה ללמוד לרכוב בלי גלגלי עזר. אבא מחזיק את האופניים מאחור. תמר לוחצת על הדוושות ונוסעת לאט.\n\nפתאום אבא עוזב את האופניים. תמר נוסעת לבד! היא שמחה מאוד, אבל אז היא מפחדת ונופלת על הדשא. הברך שלה קצת כואבת.\n\nאבא רץ אליה ושואל: את בסדר? תמר אומרת: כן, אני רק צריכה לנסות שוב. היא קמה ומנקה את המכנסיים.\n\nתמר עולה על האופניים שוב. הפעם היא נוסעת ישר ולא נופלת. הרוח נושבת בשיער שלה. היא עוברת ליד העץ הגדול ומסביב לספסל.\n\nאמא יוצאת מהבית ורואה את תמר רוכבת. היא מוחאת כפיים וקוראת: יופי, תמר! את רוכבת לבד!\n\nתמר מחייכת. עכשיו היא יודעת לרכוב על אופניים. מחר היא רוצה לרכוב עד הגן עם החברים שלה.","qpool":[{"q":"בת כמה תמר?","o":["בת חמש","בת שש","בת שבע","בת שמונה"],"c":2},{"q":"מה הצבע של האופניים?","o":["כחול","אדום","ירוק","צהוב"],"c":1},{"q":"מתי תמר קיבלה את האופניים?","o":["ביום ההולדת","בחנוכה","בפסח","בקיץ"],"c":0},{"q":"מי מחזיק את האופניים מאחור?","o":["אמא","אבא","החבר","הסבא"],"c":1},{"q":"מה קורה כשאבא עוזב?","o":["תמר עוצרת","תמר נופלת על הדשא","תמר בוכה הרבה","האופניים נשברים"],"c":1},{"q":"מה כואב לתמר?","o":["היד","הראש","הברך","הרגל"],"c":2},{"q":"מה תמר עושה אחרי שהיא נופלת?","o":["הולכת הביתה","מנסה שוב","בוכה","זורקת את האופניים"],"c":1},{"q":"מה תמר רוצה לעשות מחר?","o":["לרכוב עד הגן עם החברים","לישון כל היום","לצייר","ללכת לים"],"c":0}]},{"id":"h9","lvl":3,"title":"השכן החדש","text":"משפחה חדשה עברה לגור בבניין של איתי, בקומה השנייה, ממש מתחת לדירה שלו. יום אחד איתי ראה ילד חדש עומד ליד תיבות הדואר. הילד נראה עצוב ולא הכיר אף אחד.\n\nאיתי התקרב ואמר שלום. קוראים לי איתי, אני גר בקומה השלישית. הילד הרים את הראש ואמר: אני יונתן, עברנו לכאן אתמול. עדיין אין לי חברים בשכונה הזאת.\n\nאיתי חשב רגע ואז הציע: אתה רוצה לבוא לשחק איתי בכדור בחצר? יונתן חייך בפעם הראשונה. הוא רץ הביתה לבקש רשות מאמא שלו, ומיד חזר עם כדורגל ביד.\n\nהשניים שיחקו בחצר עד הערב. הם גילו שהם אוהבים את אותה קבוצה, ושניהם לומדים באותה כיתה בבית הספר. יונתן היה מאושר. הוא כבר לא הרגיש לבד.\n\nלפני שנפרדו, איתי אמר: מחר בבוקר נלך יחד לבית הספר. אני אחכה לך למטה בשבע וחצי. יונתן הסכים בשמחה.\n\nבערב, כשיונתן סיפר לאמא שלו על החבר החדש, היא שמחה מאוד. היא הכינה עוגה ואמרה: מחר תזמין את איתי אלינו, נכיר את המשפחה שלו.\n\nאיתי חזר הביתה עם חיוך גדול. הוא ידע שקצת אכפתיות יכולה להפוך יום עצוב של מישהו ליום שמח. לפעמים כל מה שאדם חדש צריך זה חבר אחד טוב.","qpool":[{"q":"לאיזו קומה עברה המשפחה החדשה?","o":["הראשונה","השנייה","השלישית","הרביעית"],"c":1},{"q":"איפה איתי ראה את הילד החדש בפעם הראשונה?","o":["בבית הספר","בפארק","ליד תיבות הדואר","בחנות"],"c":2},{"q":"איך נראה יונתן בהתחלה?","o":["שמח","עצוב","כועס","עייף"],"c":1},{"q":"מה איתי הציע ליונתן?","o":["לשחק בכדור בחצר","ללכת לקולנוע","לעשות שיעורים","לאכול גלידה"],"c":0},{"q":"מה גילו השניים שמשותף להם?","o":["אותו יום הולדת","אותה מכונית","אותו שם","אותה קבוצה ואותה כיתה"],"c":3},{"q":"מתי איתי יחכה ליונתן בבוקר?","o":["בשש","בשמונה","בשבע וחצי","בתשע"],"c":2},{"q":"מה אמא של יונתן הכינה?","o":["עוגה","פיצה","סלט","מרק"],"c":0},{"q":"מה איתי הבין בסוף הסיפור?","o":["שכדורגל זה כיף","שצריך ללמוד הרבה","שאסור לאחר","שקצת אכפתיות יכולה לשמח מישהו"],"c":3}]},{"id":"h10","lvl":4,"title":"ההצגה של מאיה","text":"מאיה אהבה לשחק ולהעמיד פנים בבית, אבל מול אנשים היא תמיד התביישה. לכן כשהמורה הודיעה שהכיתה תעלה הצגה בסוף השנה, הלב של מאיה פעם בחוזקה. היא רצתה מאוד להשתתף, אבל פחדה לעמוד על הבמה מול כל ההורים.\n\nהמורה חילקה את התפקידים. מאיה קיבלה את התפקיד הראשי - מלכה חכמה שמצילה את הממלכה. בהתחלה מאיה שמחה, אבל בלילה היא לא הצליחה להירדם. מה יקרה אם אשכח את המילים? מה אם כולם יצחקו עליי?\n\nבימים הבאים מאיה תרגלה את התפקיד בבית. אמא שלה ישבה מולה והקשיבה בסבלנות. כל פעם שמאיה טעתה, אמא אמרה: זה בסדר, נסי שוב. לאט לאט מאיה זכרה את כל המשפטים בעל פה.\n\nאבל בחזרה הכללית בבית הספר, כשמאיה עלתה על הבמה וראתה את הכיסאות הריקים, היא קפאה. המילים נעלמו לה מהראש. היא הרגישה שהיא רוצה לברוח. חברתה נועה, ששיחקה תפקיד קטן, לחשה לה: תסתכלי עליי, לא על הקהל. תדמייני שאנחנו רק משחקות בחדר.\n\nביום ההצגה האולם היה מלא. מאיה הציצה מאחורי הווילון וראתה את ההורים שלה יושבים בשורה הראשונה. הברכיים שלה רעדו. אבל אז היא נזכרה בעצה של נועה. היא נשמה עמוק, חשבה על החדר בבית, ועלתה לבמה.\n\nברגע שמאיה התחילה לדבר, הפחד נעלם. היא הייתה המלכה. היא זזה, דיברה וחייכה כאילו הבמה הייתה הבית שלה. הקהל הקשיב בשקט, ובסוף ההצגה כולם קמו ומחאו כפיים בהתלהבות.\n\nמאיה ירדה מהבמה מאושרת. אמא חיבקה אותה חזק ואמרה: היית נהדרת! מאיה הבינה שהפחד לא נעלם כי היא חזקה מכולם, אלא כי היא ניסתה למרות הפחד. ומאותו יום היא כבר לא פחדה לעמוד מול אנשים.","qpool":[{"q":"למה מאיה תמיד התביישה?","o":["היא לא אהבה לשחק","מול אנשים היא התביישה","היא לא ידעה לדבר","היא הייתה עייפה"],"c":1},{"q":"איזה תפקיד מאיה קיבלה?","o":["מלכה חכמה","תפקיד קטן","עץ","חייל"],"c":0},{"q":"מה הדאיג את מאיה בלילה?","o":["שתאחר לבמה","שתשכח את המילים ויצחקו עליה","שלא יהיה קהל","שהבמה תישבר"],"c":1},{"q":"מי עזרה למאיה לתרגל בבית?","o":["המורה","נועה","אמא","אבא"],"c":2},{"q":"מה קרה בחזרה הכללית?","o":["מאיה שיחקה מצוין","מאיה חלתה","מאיה קפאה ושכחה את המילים","ההצגה בוטלה"],"c":2},{"q":"מה נועה לחשה למאיה?","o":["לברוח מהבמה","לדבר חזק","לשיר","להסתכל עליה ולא על הקהל"],"c":3},{"q":"מה קרה כשמאיה התחילה לדבר בהצגה?","o":["הפחד נעלם","היא בכתה","היא שכחה הכל","היא ברחה"],"c":0},{"q":"מה מאיה הבינה בסוף?","o":["שהיא חזקה מכולם","שהיא ניצחה את הפחד כי ניסתה למרות הפחד","שהצגות זה משעמם","שעדיף לא לשחק"],"c":1}]}];
